<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:Arial;margin:40px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:8px}.brand{color:#b5121b;font-size:28px;font-weight:bold}.state{font-size:20px}@media print{button{display:none}}</style></head><body><div class="brand">SEVEN WAYS</div><h1>فاتورة مبيعات</h1><p class="state">{{ strtoupper($invoice->status) }}</p><p>{{ $invoice->invoice_number }} — {{ $invoice->branch->name }} — {{ $invoice->customer_name_snapshot }}</p><p>السيارة: {{ $invoice->vehicle_snapshot['plate_number'] ?? '-' }} — أمر العمل: {{ $invoice->workOrder?->work_order_number }}</p><table><tr><th>الوصف</th><th>الكمية</th><th>السعر</th><th>الضريبة</th><th>الإجمالي</th></tr>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->tax_amount }}</td><td>{{ $item->total }}</td></tr>@endforeach</table><p>الخصم {{ $invoice->discount_amount }} | الضريبة {{ $invoice->tax_amount }} | الإجمالي {{ $invoice->total }} | المدفوع {{ $invoice->paid_amount }} | الرصيد {{ $invoice->balance_due }}</p><p>{{ $invoice->terms_snapshot }}</p><button onclick="print()">طباعة</button></body></html>
